const avocado='<svg viewBox="0 0 40 50" aria-hidden="true"><path d="M20 2C12 2 12 12 7 21-5 43 10 50 20 48 32 50 46 38 32 20 27 13 28 2 20 2" fill="#667c48"/><path d="M20 7c-5 0-5 9-10 18-8 15 1 19 10 19s18-5 10-19c-5-9-5-18-10-18" fill="#d2d982"/><circle cx="20" cy="32" r="9" fill="#93664a"/></svg>';
const mealArt=`<svg viewBox="0 0 460 240" role="img" aria-label="איור מקומי דקורטיבי של סלט ופסטה"><rect width="460" height="240" fill="#d8dda5"/><path d="M0 175 460 100v140H0" fill="#c8d08d"/><ellipse cx="237" cy="135" rx="133" ry="83" fill="#b8c2a5" opacity=".3"/><ellipse cx="230" cy="121" rx="133" ry="83" fill="#fcfaf0"/><ellipse cx="230" cy="121" rx="105" ry="61" fill="#e7d4a8"/><g fill="none" stroke="#dbb966" stroke-width="9" stroke-linecap="round"><path d="m165 91 33 20m23-31 26 27m25-17 25 25m-115 11 29 26m26-30 29 26m-52 13 32 15m20-37 27 16m-99-33 28-9"/></g><g fill="#6d8b4f"><ellipse cx="166" cy="119" rx="17" ry="8" transform="rotate(-30 166 119)"/><ellipse cx="266" cy="86" rx="17" ry="8" transform="rotate(30 266 86)"/><ellipse cx="246" cy="151" rx="18" ry="8" transform="rotate(-20 246 151)"/><ellipse cx="201" cy="81" rx="17" ry="8"/></g><g fill="#b66d4c"><circle cx="194" cy="141" r="9"/><circle cx="280" cy="128" r="9"/><circle cx="221" cy="97" r="8"/></g><path d="m373 44-32 146m20-153-10 47m-1-49-10 48m-1-50-10 48" fill="none" stroke="#77866a" stroke-width="5" stroke-linecap="round"/><path d="M74 37c-19 35-21 51-7 58l-16 78" fill="none" stroke="#77866a" stroke-width="6" stroke-linecap="round"/></svg>`;
const roomArt=`<svg viewBox="0 0 400 450" role="img" aria-label="איור מקומי דקורטיבי של בית חם"><path d="M72 183V94a128 128 0 0 1 256 0v89" fill="#f6f3e7"/><path d="M200 33v150M75 112h250" stroke="#d5dba6" stroke-width="7"/><path d="M50 338h302" stroke="#bdc7a8" stroke-width="3"/><ellipse cx="198" cy="365" rx="153" ry="35" fill="#d5dba6"/><rect x="78" y="251" width="239" height="86" rx="22" fill="#81954d"/><rect x="91" y="207" width="212" height="93" rx="25" fill="#91a357"/><rect x="66" y="262" width="32" height="72" rx="13" fill="#6d843d"/><rect x="292" y="262" width="32" height="72" rx="13" fill="#6d843d"/><path d="M101 334v17m184-17v17" stroke="#725e46" stroke-width="8"/><rect x="112" y="229" width="62" height="55" rx="10" fill="#eeead6" transform="rotate(-8 140 250)"/><rect x="215" y="231" width="55" height="49" rx="10" fill="#d3da92" transform="rotate(7 240 250)"/><ellipse cx="194" cy="337" rx="59" ry="18" fill="#af8968"/><path d="M152 343v35m83-35v35" stroke="#8f6b4e" stroke-width="6"/><path d="M340 253v-80" stroke="#6e8257" stroke-width="4"/><g fill="#7a925f"><ellipse cx="325" cy="199" rx="11" ry="27" transform="rotate(-35 325 199)"/><ellipse cx="353" cy="177" rx="10" ry="28" transform="rotate(30 353 177)"/><ellipse cx="350" cy="225" rx="10" ry="25" transform="rotate(40 350 225)"/></g><path d="m321 252 7 51h26l7-51" fill="#ab8160"/><circle cx="195" cy="320" r="9" fill="#f5f1df"/></svg>`;
const initial={shopping:[{id:1,name:'עגבניות שרי',category:'ירקות ופירות',done:false},{id:2,name:'חלב שיבולת שועל',category:'מקרר',done:false},{id:3,name:'לחם מחמצת',category:'מאפים',done:true},{id:4,name:'אבוקדו',category:'ירקות ופירות',qty:2,done:false},{id:5,name:'ביצים',category:'מקרר וביצים',done:false},{id:6,name:'קפה',category:'מזווה',done:false}],tasks:[{id:1,title:'להשקות את העציצים',who:'רועי',when:'היום',done:false},{id:2,title:'להפעיל מכונת כביסה',who:'מאיה',when:'היום',done:false},{id:3,title:'לבחור ארוחה לערב',who:'ביחד',when:'בלי לחץ',done:false}]};let data;try{data=JSON.parse(localStorage.getItem('couple-demo-v1'))||structuredClone(initial)}catch{data=structuredClone(initial)};const save=()=>{if(window.CASA_CLOUD&&CASA_CLOUD.active)return CASA_CLOUD.onSave();try{localStorage.setItem('couple-demo-v1',JSON.stringify(data));return true}catch{toast('האחסון המקומי מלא. השינוי לא נשמר; נסו להסיר תמונה.');return false}};const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let token=sessionStorage.getItem('demo-invite')||crypto.randomUUID();sessionStorage.setItem('demo-invite',token);let revoked=sessionStorage.getItem('demo-revoked')==='true',accepted=sessionStorage.getItem('demo-accepted')==='true';const inviteUrl=()=>{const url=new URL('./',location.href);url.searchParams.set('invite',token);return url.href};const qrData=()=>`data:image/svg+xml;charset=utf-8,${encodeURIComponent(LocalQR.toSVG(inviteUrl()))}`;
function toast(text){$('.toast')?.remove();const d=document.createElement('div');d.className='toast';d.setAttribute('role','status');d.textContent=text;document.body.append(d);clearTimeout(toastTimer);toastTimer=setTimeout(()=>d.remove(),3500)}
function appHeader(){const me=myMember();const house=CASA_CLOUD.active?(CASA_CLOUD.housePending??(CASA_CLOUD.hh?.name||data.houseName)):data.houseName;return `<header class="top"><div class="side left">${avatarForMember(me)}<button class="gear" data-go="settings" aria-label="הגדרות">${gearIcon}</button></div><button class="brand centerbrand" data-go="home" aria-label="CASA בית">${casaLogo}<span class="brandtext"><span class="greeting">שלום ${esc(me.name)}</span>${house?`<span class="housechip">${esc(house)}</span>`:''}</span></button><div class="side right"><button class="iconbtn tasksbtn" data-go="tasks" aria-label="מטלות">${icon('tasks')}</button></div></header>`}

function nav(){return `<nav class="nav" aria-label="ניווט ראשי">${[['home','home','היום'],['shopping','shop','קניות'],['meals','meal','תפריט'],['expenses','money','הוצאות']].map(([p,i,t])=>`<button data-go="${p}" class="${page===p||(p==='meals'&&(page==='meal'||page==='meal-edit'))?'active':''}">${icon(i)}${t}</button>`).join('')}</nav>`}

function taskRows(list=data.tasks){return list.length?list.map(t=>`<div class="task" data-task-row="${t.id}"><button class="check ${t.done?'done':''}" data-task="${t.id}" aria-label="${t.done?'ביטול השלמה: ':'השלמה: '}${esc(t.title)}" aria-pressed="${t.done}">${t.done?'✓':''}</button><div class="tasktext ${t.done?'completed':''}">${esc(t.title)}<small>${esc(t.when)} · ${t.done?'הושלמה':'פתוחה'}</small></div><div class="task-avatars" aria-label="אחראים">${avatarsForWho(t.who)}</div><button class="quiet task-del" data-del-task="${t.id}" aria-label="מחיקת ${esc(t.title)}">מחיקה</button></div>`).join(''):'<p class="empty">אין מטלות בתצוגה הזו. אפשר לבחור סינון אחר.</p>'}
function shopRows(items){return items.map(t=>`<div class="shop-row ${t.done?'is-bought':''}" data-product="${t.id}"><button class="check purchasecheck ${t.done?'done':''}" data-shop="${t.id}" aria-label="${t.done?'החזרת ':'סימון נקנה: '}${esc(t.name)}" aria-pressed="${t.done}">${t.done?'✓':''}</button><span class="productart" aria-hidden="true">${productArt(t.art)}</span><div class="tasktext ${t.done?'completed':''}"><span class="productname">${esc(t.name)}</span><small>${esc(t.unit)}${t.fromMeal?' · מהתפריט':''}</small></div>${!t.done?`<div class="quantity" aria-label="כמות ${esc(t.name)}"><button data-qty="${t.id}" data-step="-1" aria-label="הפחתת כמות ${esc(t.name)}" ${t.qty<=1?'disabled':''}>−</button><output aria-label="כמות ${esc(t.name)}">${t.qty}</output><button data-qty="${t.id}" data-step="1" aria-label="הגדלת כמות ${esc(t.name)}" ${t.qty>=99?'disabled':''}>+</button></div><button class="edit-category" data-edit-category="${t.id}" aria-label="שינוי קטגוריה ${esc(t.name)}"><svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="m4 12 9-9 4 4-9 9-5 1Z M11 5l4 4"/></svg></button>`:`<span class="boughtquantity">${t.qty} ${esc(t.unit)}</span>`}${editingCategory===t.id&&!t.done?`<label class="categoryeditor">קטגוריה <select data-item-category="${t.id}" aria-label="קטגוריה ${esc(t.name)}">${allShoppingCategories().map(c=>`<option ${t.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`:''}</div>`).join('')}
function quick(){return `<div class="quick"><input id="quick-item" aria-label="מה חסר בבית?" placeholder="מה חסר בבית?" maxlength="90"><button id="add-item" aria-label="הוספה לקניות">+</button></div>`}
function head(title,sub,action=''){return `<div class="head"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`}
function welcome(){return `<div class="welcome"><div><div class="eyebrow">פחות לתאם. יותר להיות יחד.</div><h1>כל מה שצריך,<br>כדי להרגיש בבית.</h1><p>הקניות, הדברים הקטנים ומה נאכל הערב. מקום נעים אחד, לבית שלכם.</p><button class="primary" data-go="login">בואו נתחיל</button><button class="secondary" data-go="home">להציץ בהדגמה</button><div class="features"><span>קניות ביחד</span><span>מה עושים היום</span><span>האוכל שלנו</span></div><div class="footnote">"להציץ בהדגמה" פותח בית לדוגמה במכשיר הזה בלבד, בלי חשבון.</div></div><div class="heroscene">${roomArt}</div></div>`}
function login(){return `<div class="center"><button class="back" data-go="welcome">→ בחזרה</button><div class="card"><div class="onboardingstep">מתחילים במקום קטן ומשותף</div><h1>היי, טוב שבאתם.</h1><p>בהמשך, לכל אחד יהיה חשבון אישי. כרגע אפשר להכיר את הבית בלי להירשם ובלי למסור פרטים.</p><button class="secondary nohover" disabled>כניסה באימייל — בחיבור החשבונות בהמשך</button><button class="primary" data-go="create">כניסה להדגמה</button><div class="notice">אין כאן כניסה אמיתית, סיסמאות או חשבון ענן. הנתונים נשמרים רק בדפדפן הזה.</div></div></div>`}
function create(){return `<div class="center"><button class="back" data-go="login">→ בחזרה</button><div class="card"><div class="onboardingstep">01 / הבית המשותף · הדגמה</div><h1>מקום קטן משותף.</h1><p>נתחיל עם בית לדוגמה, ונראה איך מצרפים חברים.</p><label for="house-name">איך נקרא לבית?</label><input id="house-name" value="${esc(data.houseName||'הבית שלנו')}" maxlength="60" style="margin-top:8px"><button class="primary" id="create-home">יצירת בית להדגמה</button><div class="footnote">השם יישמר מקומית בלבד. לא נוצר חשבון או בית בשרת.</div></div></div>`}
function invite(){return `<div class="center"><button class="back" data-go="settings">→ בחזרה להגדרות</button><div class="card"><div class="onboardingstep">02 / מצטרפים יחד · הדגמה</div><h1>כמה טלפונים.<br>בית אחד.</h1><p>כשאתם יחד, הכי פשוט לסרוק במצלמה הרגילה של הטלפון. מרחוק אפשר לשתף קישור.</p>${revoked?'<div class="notice">קישור ההדגמה בוטל בדפדפן הזה.</div><button class="primary" id="renew">יצירת QR הדגמה חדש</button>':`<img class="qr" src="${qrData()}" alt="QR אמיתי של קישור הזמנה מקומי להדגמה"><div class="notice">הדגמה מקומית — עדיין לא מחבר בין טלפונים. ה־QR פותח את אותה הדגמה בלבד, בלי לצרף חשבון או לסנכרן מידע. אין בו פרטי חשבון.</div><div class="link">${esc(inviteUrl())}</div><button class="primary" id="copy-invite">העתקת קישור לשיתוף</button><button class="secondary" data-go="accept">תצוגת קבלת ההזמנה</button><button class="quiet" id="revoke" style="margin-top:18px">ביטול ההזמנה בהדגמה</button>`}<div class="footnote">במוצר האמיתי: כניסה אישית ואישור מפורש, קישור חד־פעמי שפג לאחר 24 שעות וניתן לביטול. האבטחה הזו עדיין לא מחוברת לשרת.</div></div></div>`}
function accept(){return `<div class="center"><button class="back" data-go="invite">→ בחזרה להזמנה</button><div class="card"><div class="onboardingstep">תצוגה בלבד · אין התחברות בין מכשירים</div><h1>${accepted?'השלב הבא יהיה ביחד.':'הזמנה לבית לדוגמה'}</h1><p>${accepted?'אישור ההדגמה נרשם בדפדפן הזה בלבד. לא צורף אדם לבית אמיתי.':'במוצר המלא, כאן נכנסים לחשבון אישי, בודקים לאיזה בית הוזמנתם ומאשרים הצטרפות.'}</p><div class="notice">${revoked?'ההזמנה בוטלה בהדגמה.':accepted?'ההזמנה סומנה כנוצלה בהדגמה המקומית.':'בית לדוגמה · נתוני דוגמה בלבד'}</div>${!accepted&&!revoked?'<button class="primary" id="accept-demo">הדמיית אישור הצטרפות</button>':''}<button class="secondary" data-go="home">פתיחת הבית לדוגמה</button></div></div>`}
function home(){const dinner=getMenu().find(m=>m.category==='dinner')||getMenu()[0];const todayItems=eventsOn(selectedDay);const todayLabel=formatDayLabel(todayISO());return `<div class="homedate" aria-label="התאריך היום"><span class="homedate-label">היום</span><strong>${todayLabel}</strong></div><div class="grid homegrid"><div class="stack"><section class="card calendarcard"><div class="cardhead"><h2>היומן של הבית</h2><button type="button" class="quiet" id="toggle-month-view" aria-pressed="${monthView}">${monthView?'שבועיים':'חודש מלא'}</button></div>${calendarWidget()}<div class="daypanel"><div class="cardhead"><h3>${formatDayLabel(selectedDay)}</h3><span class="sub">${todayItems.length?todayItems.length+' פריטים':'יום פתוח'}</span></div>${todayItems.length?todayItems.map(e=>`<div class="dayitem"><span class="dot ${e.kind}"></span><div><strong>${esc(e.title)}</strong><small>${esc(e.detail)}</small></div></div>`).join(''):'<p class="sub">אין אירועים ביום הזה.</p>'}</div></section>${CASA_CLOUD.active?CASA_CLOUD.upcomingCard():`<section class="card upcomingcard"><div class="cardhead"><h2>לקראת השבוע</h2></div><div class="upcoming"><div class="dateblock">יום<strong>ו׳</strong></div><div><h3>ערב קטן בבית</h3><p class="sub">בבית או בחוץ — עוד נבחר</p></div></div></section>`}</div><div class="stack"><section class="card mealcard"><div class="cardhead"><h2>מה אוכלים הערב?</h2><button class="quiet" data-go="meals">התפריט</button></div><div class="mealart">${foodArt(dinner)}</div><div class="mealinfo"><div><h3>${esc(dinner.title)}</h3><p>${dinner.time} דקות · מהמנות שאוהבים</p></div><button class="secondary" data-meal="${dinner.id}">למנה</button></div></section><section class="card quickcard"><div class="cardhead"><h2>חסר משהו?</h2><button class="quiet" data-go="shopping">הרשימה</button></div>${quick()}<div class="sub">${data.shopping.filter(t=>!t.done).length} פריטים מחכים בקניות</div></section></div></div>`}

function shopping(){const open=data.shopping.filter(t=>!t.done),bought=data.shopping.filter(t=>t.done),categories=allShoppingCategories().filter(c=>open.some(t=>t.category===c));if(shopFilter!=='all'&&!categories.includes(shopFilter))shopFilter='all';const progress=data.shopping.length?Math.round(bought.length/data.shopping.length*100):0;const suggestions=shoppingSuggestions();const planned=getPlannedDishes();return `${head('מה חסר בבית?','רשימה חכמה יותר, עדיין פשוטה בסופר.')}<div class="shoppinglayout"><div class="shoppingmain"><section class="card shopcomposer"><div class="cardhead"><h2>מוסיפים לרשימה</h2><span class="sub">${T('משותף לחברי הבית','הדגמה מקומית')}</span></div><div class="quick"><input id="quick-item" aria-label="מה חסר בבית?" placeholder="למשל חלב, אבוקדו או סבון…" maxlength="90" autocomplete="off"><button id="add-item" aria-label="הוספה לקניות">+</button></div><div class="addoptions"><label>כמות <input id="add-qty" aria-label="כמות להוספה" type="number" min="1" max="99" step="1" value="1" inputmode="numeric"></label><label>יחידה <select id="add-unit" aria-label="יחידה להוספה"><option>יח׳</option><option>חבילות</option><option>בקבוקים</option></select></label></div><p id="add-error" role="alert"></p><p id="classification-hint" class="sub">סיווג לפי מילון עברית מקומי, בלי AI. תמיד אפשר לשנות קטגוריה.</p><div class="quickproducts" aria-label="הצעות מהירות">${suggestions.map(n=>`<button data-common="${esc(n)}">+ ${esc(n)}</button>`).join('')}</div>${planned.length?`<div class="plannedbox"><div class="cardhead"><h3>מהתפריט המתוכנן</h3><span class="sub">${planned.length} מנות</span></div>${planned.map(m=>`<button class="secondary planned-btn" data-add-dish="${m.id}">+ רכיבי ${esc(m.title)}</button>`).join('')}</div>`:''}</section><div class="shoppingfilters" aria-label="סינון קטגוריות"><button data-shop-filter="all" aria-pressed="${shopFilter==='all'}" class="${shopFilter==='all'?'selected':''}">הכול</button>${categories.map(c=>`<button data-shop-filter="${esc(c)}" aria-pressed="${shopFilter===c}" class="${shopFilter===c?'selected':''}">${esc(c)}</button>`).join('')}</div><div class="categorygroups">${open.length?categories.filter(c=>shopFilter==='all'||shopFilter===c).map(c=>`<section class="card grocerygroup"><div class="cardhead"><h2>${esc(c)}</h2><span class="sub">${open.filter(t=>t.category===c).length} פריטים</span></div>${shopRows(open.filter(t=>t.category===c))}</section>`).join(''):'<section class="card"><h2>הכול כבר בסל.</h2><p>אפשר להוסיף עוד משהו, או להחזיר פריט מהרשימה שנקנתה.</p></section>'}</div><section class="card boughtsection"><button class="boughtheader" id="toggle-bought" aria-expanded="${boughtExpanded}"><span>כבר בסל <span class="sub">(${bought.length})</span></span><span aria-hidden="true">${boughtExpanded?'−':'+'}</span></button>${boughtExpanded?(bought.length?shopRows(bought)+`<button class="secondary" id="clear-bought" style="margin-top:14px">ניקוי הפריטים שנקנו</button>`:'<p class="sub" style="margin-top:14px">עדיין לא סומן פריט כנקנה.</p>'):'<p class="sub">הפריטים נשמרים כאן. אפשר לפתוח ולהחזיר לרשימה.</p>'}</section></div><aside class="card shoppingprogress"><span class="eyebrow">בסיבוב הזה</span><h2>עוד ${open.length} פריטים לקנייה</h2><p>${bought.length} מתוך ${data.shopping.length} כבר בסל</p><div class="progressbar" role="progressbar" aria-label="פריטים שנקנו" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}"><span style="width:${progress}%"></span></div><div class="notice">${T('מסונכרן בין הטלפונים · כל שינוי מופיע אצל חברי הבית.','נתוני דוגמה · השינויים נשמרים רק בדפדפן הזה. עדיין אין סנכרון בין טלפונים.')}</div></aside></div>`}

function tasks(){const filtered=data.tasks.filter(t=>(taskStatus==='all'||(taskStatus==='done'?t.done:!t.done))&&(taskOwner==='all'||t.who===taskOwner));return `<button class="back" data-go="home">→ בחזרה לבית</button>${head('מטלות','רשימה קצרה של דברים לעשות בבית.')}<section class="card taskpage"><div class="cardhead"><h2>בקצב של הבית</h2><span class="sub">${data.tasks.filter(t=>!t.done).length} פתוחות</span></div><div class="filtertabs" aria-label="סינון מצב">${[['all','הכול'],['open','פתוחות'],['done','הושלמו']].map(([v,l])=>`<button data-status="${v}" aria-pressed="${taskStatus===v}" class="${taskStatus===v?'selected':''}">${l}</button>`).join('')}</div><label class="selectlabel">לפי אחראי <select id="task-owner"><option value="all" ${taskOwner==='all'?'selected':''}>כולם</option>${whoOptions(taskOwner,true)}</select></label><div id="task-list">${taskRows(filtered)}</div><div class="addtask"><h3>עוד משהו קטן?</h3><input id="task-title" aria-label="שם מטלה חדשה" placeholder="מה צריך לעשות?" maxlength="100"><div class="taskfields"><label>מי מטפל?<select id="new-task-owner">${whoOptions(myMember().key,true)}</select></label><label>מתי?<select id="new-task-when"><option>היום</option><option>מחר</option><option>השבוע</option><option>בלי לחץ</option></select></label><button class="primary" id="add-task">הוספת מטלה</button></div></div>${T('','<div class="notice">השלמה, הוספה ומחיקה נשמרות מקומית בלבד.</div>')}</section>`}
function meals(){ensureMenu();const groups=menuCategories.map(c=>({...c,items:getMenu().filter(m=>m.category===c.id)}));return `${head('התפריט של CASA','האוכל של הבית, מסודר כמו במסעדה קטנה.')}<div class="menubook"><div class="menubook-top"><span>תפריט הבית</span><span>CASA</span></div>${groups.map(g=>`<section class="menusection" id="menu-${g.id}"><div class="menusection-head"><h2>${g.label}</h2><span class="ornament">✦</span></div>${g.items.length?g.items.map(m=>`<article class="menudish"><button class="menudish-main" data-meal="${m.id}" aria-label="פרטי ${esc(m.title)}"><div class="menudish-visual" aria-hidden="true">${foodArt(m)}</div><div class="menudish-row"><span class="menudish-name">${esc(m.title)}</span><span class="leaders" aria-hidden="true"></span><span class="menudish-time">${m.time}'</span></div><p class="menudish-note">${esc(m.note||m.instructions||'')}</p><p class="menudish-ings"><span>רכיבים</span> ${m.ingredients.map(esc).join(' · ')}</p></button><div class="menudish-actions"><button class="quiet" data-edit-meal="${m.id}">עריכה</button><button class="quiet" data-plan-meal="${m.id}">לתכנון השבוע</button></div></article>`).join(''):'<p class="sub">עדיין אין מנות בקטגוריה הזו.</p>'}</section>`).join('')}<div class="menu-add card"><h3>מנה חדשה לתפריט</h3><p class="sub">${T('משותפת לחברי הבית. לא מאגר ציבורי.','נשמרת רק במכשיר הזה. לא מאגר ציבורי.')}</p><button class="primary" data-go="meal-edit">הוספת מנה</button></div></div>${T('','<div class="notice">תפריט פרטי לדוגמה. האיורים דקורטיביים מקומיים.</div>')}`}

function meal(){const m=getMenu().find(m=>m.id===selectedMeal)||getMenu()[0];return `<button class="back" data-go="meals">→ בחזרה לתפריט</button>${head(m.title,`${m.time} דקות · רכיבים ומצרכים לקניות`)}<div class="grid"><section class="card"><div class="mealart" style="height:220px">${foodArt(m)}</div><h2>בקצרה</h2><p style="margin-top:10px">${esc(m.instructions||m.note||'')}</p><h3 style="margin-top:18px">רכיבים</h3><ul class="inglist">${m.ingredients.map(n=>`<li>${esc(n)}</li>`).join('')}</ul><button class="secondary" data-edit-meal="${m.id}" style="margin-top:16px">עריכת המנה</button></section><section class="card"><h2>מה חסר לנו?</h2><p style="margin-top:8px">בחרו רק מה שצריך לקנות.</p>${m.ingredients.map(n=>`<label class="task"><input type="checkbox" name="ingredient" value="${esc(n)}" style="width:21px;height:21px;accent-color:var(--green)"><span>${n}</span></label>`).join('')}<button class="primary" id="ingredients" style="margin-top:20px">הוספת הנבחרים לקניות</button><button class="secondary" id="add-all-ingredients" style="margin-top:10px">הוספת כל הרכיבים</button><div class="footnote">פריטים שכבר ברשימה הפתוחה ימוזגו לכמות במקום כפילות.</div></section></div>`}


const expenseCategories=[
{id:'fun',label:'בילויים',icon:'🎉'},
{id:'super',label:'סופר',icon:'🛒'},
{id:'flights',label:'טיסות',icon:'✈️'},
{id:'housing',label:'דיור/שכירות',icon:'🏠'},
{id:'bills',label:'חשבונות',icon:'💡'},
{id:'transport',label:'תחבורה',icon:'🚌'},
{id:'health',label:'בריאות',icon:'💊'},
{id:'shopping',label:'קניות',icon:'🛍️'},
{id:'other',label:'אחר',icon:'✨'}
];
let expenseView='month'; // month | analysis
let expenseChartMode='month'; // month | week for bar
let expenseChartType='bar'; // bar | pie
let expenseMonth=null; // YYYY-MM
function monthKeyFromISO(iso){return iso.slice(0,7)}
function currentMonthKey(){return monthKeyFromISO(todayISO())}
function monthLabel(ym){const [y,m]=ym.split('-').map(Number);const d=new Date(y,m-1,12);return d.toLocaleDateString('he-IL',{month:'long',year:'numeric',timeZone:'Europe/Prague'})}
function seedExpenses(){const now=todayISO();const [y,m]=now.split('-').map(Number);const mk=(yy,mm,dd)=>`${yy}-${String(mm).padStart(2,'0')}-${String(dd).padStart(2,'0')}`;const months=[];for(let i=3;i>=0;i--){let mm=m-i,yy=y;while(mm<=0){mm+=12;yy-=1}months.push([yy,mm])}
const samples=[
['super','קניות שבועיות',420,'רועי'],['fun','ערב במסעדה',380,'מאיה'],['transport','נסיעות חודש',160,'רועי'],['bills','חשמל ומים',540,'מאיה'],['shopping','כלי בית',220,'רועי'],['health','בית מרקחת',95,'מאיה'],['fun','קולנוע',140,'רועי'],['super','ירקות ופירות',185,'מאיה'],['other','מתנה',250,'רועי'],['flights','טיסה קצרה',1280,'מאיה'],['housing','שכירות חלקית',3500,'רועי'],['transport','מונית',78,'מאיה'],['super','סופר גדול',610,'רועי'],['fun','בילוי עם חברים',260,'מאיה'],['bills','אינטרנט',99,'רועי'],['shopping','בגדים',340,'מאיה'],['health','רופא שיניים',450,'רועי'],['super','קניות מהירות',130,'מאיה'],['fun','הופעה',320,'רועי'],['other','שונות',75,'מאיה']
];
const out=[];let id=1;
months.forEach(([yy,mm],mi)=>{
  const days=[3,5,8,11,14,17,20,22,25,27];
  samples.forEach((s,si)=>{
    if((si+mi)%2===0 || mi===months.length-1){
      const day=days[si%days.length];
      const amount=Math.round(s[2]*(0.85+((si+mi)%5)*0.07));
      out.push({id:id++,date:mk(yy,mm,Math.min(day,28)),title:s[1],amount,category:s[0],who:s[3]});
    }
  });
});
return out}
function ensureExpenses(){if(CASA_CLOUD.active){if(!data.expenses)data.expenses=[]}else if(!data.expenses||!data.expenses.length){data.expenses=seedExpenses();save()}if(!expenseMonth)expenseMonth=currentMonthKey()}
function expensesInMonth(ym){ensureExpenses();return data.expenses.filter(e=>monthKeyFromISO(e.date)===ym).sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id)}
function expenseMonths(){ensureExpenses();const set=new Set(data.expenses.map(e=>monthKeyFromISO(e.date)));set.add(currentMonthKey());return [...set].sort().reverse()}
function catMeta(id){return expenseCategories.find(c=>c.id===id)||expenseCategories[expenseCategories.length-1]}
function formatCZK(n){return new Intl.NumberFormat('he-IL').format(Math.round(n))+' CZK'}
function expenses(){ensureExpenses();if(expenseView==='analysis')return expensesAnalysis();
const months=expenseMonths();if(!months.includes(expenseMonth))expenseMonth=months[0];
const list=expensesInMonth(expenseMonth);const total=list.reduce((s,e)=>s+e.amount,0);
const mi=months.indexOf(expenseMonth);
return `${head('הוצאות','מתחדש בתחילת כל חודש')}
<div class="exp-toolbar">
<button type="button" class="exp-navbtn" id="exp-next" ${mi<=0?'disabled':''} aria-label="חודש הבא"><span aria-hidden="true">›</span></button>
<div class="exp-monthpick"><strong>${monthLabel(expenseMonth)}</strong><span class="sub">${list.length} הוצאות</span></div>
<button type="button" class="exp-navbtn" id="exp-prev" ${mi>=months.length-1?'disabled':''} aria-label="חודש קודם"><span aria-hidden="true">‹</span></button>
<button type="button" class="exp-review" id="exp-analysis" aria-label="סקירת הוצאות"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 19V5"/><path d="M4 19h16"/><path d="M8 16v-5"/><path d="M12 16V8"/><path d="M16 16v-3"/></svg><span>סקירה</span></button>
</div>
<section class="card exp-summary"><span class="sub">סה״כ החודש</span><div class="expense" dir="ltr">${formatCZK(total)}</div></section>
<section class="card"><div class="cardhead"><h2>פירוט</h2><button class="quiet" id="exp-add-toggle">+ הוצאה</button></div>
<div id="exp-add-form" class="exp-add" hidden style="display:none">
<label>סכום (CZK)<input id="exp-amount" type="number" min="1" max="999999" step="1" inputmode="numeric" placeholder="0"></label>
<label>תיאור<input id="exp-title" maxlength="80" placeholder="למשל סופר / מסעדה"></label>
<label>קטגוריה<select id="exp-cat">${expenseCategories.map(c=>`<option value="${c.id}">${c.icon} ${c.label}</option>`).join('')}</select></label>
<label>תאריך<input id="exp-date" type="date" value="${todayISO()}"></label>
<label>מי שילם?<select id="exp-who">${whoOptions(myMember().key,false)}</select></label>
<button class="primary" id="exp-save">שמירת הוצאה</button>
</div>
${list.length?list.map(e=>{const c=catMeta(e.category);return `<div class="exp-row"><span class="exp-ico" aria-hidden="true">${c.icon}</span><div class="exp-main"><strong>${esc(e.title)}</strong><small>${esc(c.label)} · ${formatDayLabel(e.date)} · ${esc(whoName(e.who))}</small></div><strong class="exp-amt" dir="ltr">${formatCZK(e.amount)}</strong><button class="quiet exp-del" data-del-exp="${e.id}" aria-label="מחיקת ${esc(e.title)}">מחיקה</button></div>`}).join(''):'<p class="empty">אין הוצאות בחודש הזה. אפשר להוסיף.</p>'}
</section>`}
function weekKey(iso){const d=localNoon(iso);const s=startOfWeek(d);return localIso(s)}
function expensesAnalysis(){ensureExpenses();
const byMonth={};data.expenses.forEach(e=>{const k=monthKeyFromISO(e.date);byMonth[k]=(byMonth[k]||0)+e.amount});
const months=Object.keys(byMonth).sort();
const byWeek={};data.expenses.forEach(e=>{const k=weekKey(e.date);byWeek[k]=(byWeek[k]||0)+e.amount});
const weeks=Object.keys(byWeek).sort().slice(-8);
const byCat={};data.expenses.forEach(e=>{byCat[e.category]=(byCat[e.category]||0)+e.amount});
const catEntries=Object.entries(byCat).sort((a,b)=>b[1]-a[1]);
const total=catEntries.reduce((s,[,v])=>s+v,0)||1;
return `${head('סקירת הוצאות','לאן הכסף שלנו הולך')}
<div class="exp-toolbar"><button class="secondary" id="exp-back-month">→ חזרה לחודש</button>
<div class="filtertabs" aria-label="סוג גרף">
<button data-chart-type="bar" class="${expenseChartType==='bar'?'selected':''}" aria-pressed="${expenseChartType==='bar'}">עמודות</button>
<button data-chart-type="pie" class="${expenseChartType==='pie'?'selected':''}" aria-pressed="${expenseChartType==='pie'}">עוגה</button>
</div></div>
${expenseChartType==='bar'?`<section class="card"><div class="cardhead"><h2>הוצאות לפי ${expenseChartMode==='month'?'חודש':'שבוע'}</h2>
<div class="filtertabs">${[['month','חודש'],['week','שבוע']].map(([v,l])=>`<button data-chart-mode="${v}" class="${expenseChartMode===v?'selected':''}" aria-pressed="${expenseChartMode===v}">${l}</button>`).join('')}</div></div>
${barChart(expenseChartMode==='month'?months.map(k=>({label:monthLabel(k).replace(' ', '·'),value:byMonth[k]})):weeks.map(k=>({label:k.slice(5),value:byWeek[k]})))}
</section>`:`<section class="card"><div class="cardhead"><h2>לאן הכסף הולך</h2><span class="sub">לפי קטגוריה</span></div>
${pieChart(catEntries.map(([id,v])=>({id,label:catMeta(id).label,icon:catMeta(id).icon,value:v,pct:Math.round(v/total*100)})))}
</section>`}`}
function barChart(items){if(!items.length)return '<p class="empty">אין מספיק נתונים</p>';const max=Math.max(...items.map(i=>i.value),1);const w=320,h=180,pad=28,gap=8;const bw=Math.max(10,(w-pad*2-gap*(items.length-1))/items.length);
const bars=items.map((it,i)=>{const x=pad+i*(bw+gap);const bh=(it.value/max)*(h-pad*1.6);const y=h-pad-bh;return `<rect class="bar" x="${x}" y="${y}" width="${bw}" height="${bh}" rx="4" fill="#6F9A3C"/><text x="${x+bw/2}" y="${h-8}" text-anchor="middle" font-size="9" fill="#F6EEB8">${esc(it.label)}</text>`}).join('');
return `<div class="chartwrap" dir="ltr"><svg viewBox="0 0 ${w} ${h}" class="barchart" role="img" aria-label="גרף עמודות הוצאות">${bars}</svg><ul class="chartlegend">${items.map(it=>`<li><span>${esc(it.label)}</span><strong dir="ltr">${formatCZK(it.value)}</strong></li>`).join('')}</ul></div>`}
function pieChart(items){if(!items.length)return '<p class="empty">אין מספיק נתונים</p>';const colors=['#6F9A3C','#8B5A2B','#F1DD81','#86AF37','#C46A45','#2F4A1E','#A56B38','#CFE0A8','#E8A87C'];
const cx=110,cy=100,r=78,ri=42;let a=-Math.PI/2;const total=items.reduce((s,i)=>s+i.value,0)||1;
const slices=items.map((it,i)=>{const ang=it.value/total*Math.PI*2;const a2=a+ang;const x1=cx+r*Math.cos(a),y1=cy+r*Math.sin(a),x2=cx+r*Math.cos(a2),y2=cy+r*Math.sin(a2);const xi1=cx+ri*Math.cos(a),yi1=cy+ri*Math.sin(a),xi2=cx+ri*Math.cos(a2),yi2=cy+ri*Math.sin(a2);const large=ang>Math.PI?1:0;const d=`M ${x1} ${y1} A ${r} ${r} 0 ${large} 1 ${x2} ${y2} L ${xi2} ${yi2} A ${ri} ${ri} 0 ${large} 0 ${xi1} ${yi1} Z`;a=a2;return `<path d="${d}" fill="${colors[i%colors.length]}"><title>${esc(it.label)} ${it.pct}%</title></path>`}).join('');
return `<div class="chartwrap"><svg viewBox="0 0 220 200" class="piechart" role="img" aria-label="גרף עוגה לפי קטגוריה">${slices}<circle cx="${cx}" cy="${cy}" r="${ri-2}" fill="#243816"/></svg><ul class="chartlegend pieleg">${items.map((it,i)=>`<li><span class="swatch" style="background:${colors[i%colors.length]}"></span><span>${it.icon} ${esc(it.label)}</span><strong>${it.pct}% · <span dir="ltr">${formatCZK(it.value)}</span></strong></li>`).join('')}</ul></div>`}
